<?php declare(strict_types=1);namespace StudPulse\Security;use StudPulse\Config;final class Crypto{public static function token():string{return rtrim(strtr(base64_encode(random_bytes(32)),'+/','-_'),'=');}public static function hash(string$raw):string{return hash_hmac('sha256',$raw,Config::get('SESSION_SECRET'));}public static function encrypt(string$plain):string{$nonce=random_bytes(SODIUM_CRYPTO_SECRETBOX_NONCEBYTES);return Config::get('TOKEN_KEY_ID','v1').'.'.base64_encode($nonce.sodium_crypto_secretbox($plain,$nonce,base64_decode(Config::get('TOKEN_ENCRYPTION_KEY'),true)));}public static function decrypt(string$cipher):string{[$kid,$encoded]=explode('.',$cipher,2);$key=$kid===Config::get('TOKEN_KEY_ID','v1')?Config::get('TOKEN_ENCRYPTION_KEY'):Config::get('TOKEN_PREVIOUS_KEY_'.strtoupper($kid));$raw=base64_decode($encoded,true);$decodedKey=base64_decode($key,true);if(!$raw||!$decodedKey||strlen($decodedKey)!==32){throw new \RuntimeException('Encryption key unavailable');}$plain=sodium_crypto_secretbox_open(substr($raw,24),substr($raw,0,24),$decodedKey);if($plain===false){throw new \RuntimeException('Ciphertext authentication failed');}return$plain;}}